168	macro_rules! impl_numeric_stepper_nonzero_int {
169	    ($nonzero:ty, $inner:ty) => {
170	        impl NumberFieldType for $nonzero {
171	            fn default_step() -> Self {
172	                <$nonzero>::new(1).unwrap()
173	            }
174	
175	            fn large_step() -> Self {
176	                <$nonzero>::new(10).unwrap()
177	            }
178	
179	            fn small_step() -> Self {
180	                <$nonzero>::new(1).unwrap()
181	            }
182	
183	            fn min_value() -> Self {
184	                <$nonzero>::MIN
185	            }
186	
187	            fn max_value() -> Self {
188	                <$nonzero>::MAX
189	            }
190	
191	            fn saturating_add(self, rhs: Self) -> Self {
192	                let result = self.get().saturating_add(rhs.get());
193	                <$nonzero>::new(result.max(1)).unwrap()
194	            }
195	
196	            fn saturating_sub(self, rhs: Self) -> Self {
197	                let result = self.get().saturating_sub(rhs.get()).max(1);
198	                <$nonzero>::new(result).unwrap()
199	            }
200	        }
201	    };
