204	macro_rules! impl_numeric_stepper_float {
205	    ($type:ident) => {
206	        impl NumberFieldType for $type {
207	            fn default_format(value: &Self) -> String {
208	                format!("{:.2}", value)
209	            }
210	
211	            fn default_step() -> Self {
212	                1.0
213	            }
214	
215	            fn large_step() -> Self {
216	                10.0
217	            }
