224	                <$type>::MIN
225	            }
226	
227	            fn max_value() -> Self {
228	                <$type>::MAX
229	            }
230	
231	            fn saturating_add(self, rhs: Self) -> Self {
232	                (self + rhs).clamp(Self::min_value(), Self::max_value())
233	            }
234	
235	            fn saturating_sub(self, rhs: Self) -> Self {
236	                (self - rhs).clamp(Self::min_value(), Self::max_value())
237	            }
238	        }
239	    };
