282	impl<T: NumberFieldType> NumberField<T> {
283	    pub fn new(id: impl Into<ElementId>, value: T, window: &mut Window, cx: &mut App) -> Self {
284	        let id = id.into();
285	
286	        let (mode, focus_handle, edit_editor, on_change_state, last_synced_value) =
287	            window.with_id(id.clone(), |window| {
288	                let mode = window.use_state(cx, |_, _| NumberFieldMode::default());
289	                let focus_handle = window.use_state(cx, |_, cx| cx.focus_handle());
290	                let edit_editor = window.use_state(cx, |_, _| None);
291	                let on_change_state: Entity<Option<OnChangeCallback<T>>> =
292	                    window.use_state(cx, |_, _| None);
293	                let last_synced_value: Entity<Option<T>> = window.use_state(cx, |_, _| None);
294	                (
295	                    mode,
296	                    focus_handle,
297	                    edit_editor,
298	                    on_change_state,
299	                    last_synced_value,
300	                )
301	            });
302	
303	        Self {
304	            id,
305	            mode,
306	            edit_editor,
307	            on_change_state,
308	            last_synced_value,
309	            value,
310	            focus_handle: focus_handle.read(cx).clone(),
311	            format: Box::new(T::default_format),
312	            large_step: T::large_step(),
313	            step: T::default_step(),
314	            small_step: T::small_step(),
315	            min_value: T::min_value(),
316	            max_value: T::max_value(),
317	            on_reset: None,
318	            on_change: Rc::new(|_, _, _| {}),
319	            tab_index: None,
320	            aria_label: None,
321	            aria_description: None,
322	        }
323	    }
324	
325	    pub fn min(mut self, min: T) -> Self {
326	        self.min_value = min;
327	        self
328	    }
329	
330	    pub fn max(mut self, max: T) -> Self {
331	        self.max_value = max;
332	        self
333	    }
334	
335	    pub fn mode(self, mode: NumberFieldMode, cx: &mut App) -> Self {
336	        self.mode.write(cx, mode);
337	        self
338	    }
339	
340	    pub fn tab_index(mut self, tab_index: isize) -> Self {
341	        self.tab_index = Some(tab_index);
342	        self
343	    }
344	
345	    pub fn on_change(mut self, on_change: impl Fn(&T, &mut Window, &mut App) + 'static) -> Self {
346	        self.on_change = Rc::new(on_change);
347	        self
348	    }
349	
350	    /// Sets the label announced by assistive technology.
351	    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
352	        self.aria_label = Some(label.into());
353	        self
354	    }
355	
356	    /// Sets the supplementary description announced by assistive technology
357	    /// after the field's name, role, and value.
358	    pub fn aria_description(mut self, description: impl Into<SharedString>) -> Self {
359	        self.aria_description = Some(description.into());
360	        self
361	    }
362	
363	    fn sync_on_change_state(&self, cx: &mut App) {
364	        self.on_change_state
365	            .update(cx, |state, _| *state = Some(self.on_change.clone()));
366	    }
367	}
368	
369	#[derive(Clone, Copy)]
370	enum ValueChangeDirection {
371	    Increment,
372	    Decrement,
373	}
374	
375	/// Best-effort conversion of a numeric field value to `f64` for reporting to
376	/// assistive technology. Goes through the `Display` representation because
377	/// `NumberFieldType` has no general numeric conversion.
378	fn a11y_numeric_value(value: &impl Display) -> Option<f64> {
379	    format!("{}", value).parse::<f64>().ok()
380	}
381	
382	/// Best-effort conversion of an assistive-technology-provided `f64` back into
383	/// a field value. Falls back to the rounded value for integer field types.
384	fn a11y_value_to_field_value<T: NumberFieldType>(value: f64) -> Option<T> {
385	    format!("{}", value)
386	        .parse::<T>()
387	        .ok()
388	        .or_else(|| format!("{}", value.round()).parse::<T>().ok())
389	}
390	
391	impl<T: NumberFieldType> RenderOnce for NumberField<T> {
392	    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
393	        // Sync the on_change callback to Entity state so focus_out handlers can access it
394	        self.sync_on_change_state(cx);
395	
396	        let is_edit_mode = matches!(*self.mode.read(cx), NumberFieldMode::Edit);
397	
398	        let get_step = {
399	            let large_step = self.large_step;
400	            let step = self.step;
401	            let small_step = self.small_step;
402	            move |modifiers: Modifiers| -> T {
403	                if modifiers.shift {
404	                    large_step
405	                } else if modifiers.alt {
406	                    small_step
407	                } else {
408	                    step
409	                }
410	            }
411	        };
412	
413	        let clamp_value = {
414	            let min = self.min_value;
415	            let max = self.max_value;
416	            move |value: T| -> T {
417	                if value < min {
418	                    min
419	                } else if value > max {
420	                    max
421	                } else {
422	                    value
423	                }
424	            }
425	        };
426	
427	        let change_value = {
428	            move |current: T, step: T, direction: ValueChangeDirection| -> T {
429	                let new_value = match direction {
430	                    ValueChangeDirection::Increment => current.saturating_add(step),
431	                    ValueChangeDirection::Decrement => current.saturating_sub(step),
432	                };
433	                clamp_value(new_value)
434	            }
435	        };
436	
437	        let get_current_value = {
438	            let value = self.value;
439	            let edit_editor = self.edit_editor.clone();
440	
441	            Rc::new(move |cx: &App| -> T {
442	                if !is_edit_mode {
443	                    return value;
444	                }
445	                edit_editor
446	                    .read(cx)
447	                    .as_ref()
448	                    .and_then(|weak| weak.upgrade())
449	                    .and_then(|editor| editor.read(cx).text(cx).parse::<T>().ok())
450	                    .unwrap_or(value)
451	            })
452	        };
453	
454	        let update_editor_text = {
455	            let edit_editor = self.edit_editor.clone();
456	
457	            Rc::new(move |new_value: T, window: &mut Window, cx: &mut App| {
458	                if !is_edit_mode {
459	                    return;
460	                }
461	                let Some(editor) = edit_editor
462	                    .read(cx)
463	                    .as_ref()
464	                    .and_then(|weak| weak.upgrade())
465	                else {
466	                    return;
467	                };
468	                editor.update(cx, |editor, cx| {
469	                    editor.set_text(format!("{}", new_value), window, cx);
470	                });
471	            })
472	        };
473	
474	        let step_value = {
475	            let on_change = self.on_change.clone();
476	            let get_current_value = get_current_value.clone();
477	            let update_editor_text = update_editor_text.clone();
478	
479	            Rc::new(
480	                move |direction: ValueChangeDirection,
481	                      modifiers: Modifiers,
482	                      window: &mut Window,
483	                      cx: &mut App| {
484	                    let current_value = get_current_value(cx);
485	                    let step = get_step(modifiers);
486	                    let new_value = change_value(current_value, step, direction);
487	
488	                    update_editor_text(new_value, window, cx);
489	                    on_change(&new_value, window, cx);
490	                },
491	            )
492	        };
493	
494	        let set_value = {
495	            let on_change = self.on_change.clone();
496	            let update_editor_text = update_editor_text.clone();
497	
498	            move |raw_value: f64, window: &mut Window, cx: &mut App| {
499	                let Some(parsed) = a11y_value_to_field_value::<T>(raw_value) else {
500	                    return;
501	                };
502	                let new_value = clamp_value(parsed);
503	                update_editor_text(new_value, window, cx);
504	                on_change(&new_value, window, cx);
505	            }
506	        };
507	
508	        let bg_color = cx.theme().colors().surface_background;
509	        let hover_bg_color = cx.theme().colors().element_hover;
510	
511	        let border_color = cx.theme().colors().border_variant;
512	        let focus_border_color = cx.theme().colors().border_focused;
513	
514	        let base_button = |icon: IconName| {
515	            h_flex()
516	                .cursor_pointer()
517	                .p_1p5()
518	                .size_full()
519	                .justify_center()
520	                .overflow_hidden()
521	                .border_1()
522	                .border_color(border_color)
523	                .bg(bg_color)
524	                .hover(|s| s.bg(hover_bg_color))
525	                .focus_visible(|s| s.border_color(focus_border_color).bg(hover_bg_color))
526	                .child(Icon::new(icon).size(IconSize::Small))
527	        };
528	
529	        h_flex()
530	            .id(self.id.clone())
531	            .role(Role::SpinButton)
532	            .when_some(self.aria_label.clone(), |this, label| {
533	                this.aria_label(label)
534	            })
535	            .when_some(self.aria_description.clone(), |this, description| {
536	                this.aria_description(description)
537	            })
538	            .when_some(a11y_numeric_value(&self.value), |this, value| {
539	                this.aria_numeric_value(value)
540	            })
541	            .when_some(a11y_numeric_value(&self.min_value), |this, min| {
542	                this.aria_min_numeric_value(min)
543	            })
544	            .when_some(a11y_numeric_value(&self.max_value), |this, max| {
545	                this.aria_max_numeric_value(max)
546	            })
547	            .when_some(a11y_numeric_value(&self.step), |this, step| {
548	                this.aria_numeric_value_step(step)
549	            })
550	            // Some assistive technology (e.g. Orca via AT-SPI's Value
551	            // interface) can only set an absolute value, while other screen
552	            // readers dispatch Increment/Decrement, so support all three.
553	            .on_a11y_action(AccessibleAction::SetValue, {
554	                move |data, window, cx| {
555	                    if let Some(gpui::accesskit::ActionData::NumericValue(value)) = data {
556	                        set_value(*value, window, cx);
557	                    }
558	                }
559	            })
560	            .on_a11y_action(AccessibleAction::Increment, {
561	                let step_value = step_value.clone();
562	                move |_, window, cx| {
563	                    step_value(
564	                        ValueChangeDirection::Increment,
565	                        Modifiers::default(),
566	                        window,
567	                        cx,
568	                    );
569	                }
570	            })
571	            .on_a11y_action(AccessibleAction::Decrement, {
572	                let step_value = step_value.clone();
573	                move |_, window, cx| {
574	                    step_value(
575	                        ValueChangeDirection::Decrement,
576	                        Modifiers::default(),
577	                        window,
578	                        cx,
579	                    );
580	                }
581	            })
582	            .track_focus(&self.focus_handle)
583	            .gap_1()
584	            .when_some(self.on_reset, |this, on_reset| {
585	                this.child(
586	                    IconButton::new("reset", IconName::RotateCcw)
587	                        .icon_size(IconSize::Small)
588	                        .aria_label("Reset to Default")
589	                        .when_some(self.tab_index, |this, _| this.tab_index(0isize))
590	                        .on_click(on_reset),
591	                )
592	            })
593	            .child({
594	                h_flex()
595	                    .map(|decrement| {
596	                        let decrement_handler = {
597	                            let step_value = step_value.clone();
598	
599	                            move |click: &ClickEvent, window: &mut Window, cx: &mut App| {
600	                                step_value(
601	                                    ValueChangeDirection::Decrement,
602	                                    click.modifiers(),
603	                                    window,
604	                                    cx,
605	                                );
606	                            }
607	                        };
608	
609	                        decrement.child(
610	                            base_button(IconName::Dash)
611	                                .id((self.id.clone(), "decrement_button"))
612	                                .role(Role::Button)
613	                                .aria_label("Decrement")
614	                                .rounded_tl_sm()
615	                                .rounded_bl_sm()
616	                                .when_some(self.tab_index, |this, _| this.tab_index(0isize))
617	                                .on_click(decrement_handler),
618	                        )
619	                    })
620	                    .child({
621	                        h_flex()
622	                            .min_w_16()
623	                            .size_full()
624	                            .border_y_1()
625	                            .border_color(border_color)
626	                            .bg(bg_color)
627	                            .in_focus(|this| this.border_color(focus_border_color))
628	                            .child(match *self.mode.read(cx) {
629	                                NumberFieldMode::Read => h_flex()
630	                                    .px_1()
631	                                    .flex_1()
632	                                    .justify_center()
633	                                    .child(
634	                                        Label::new((self.format)(&self.value)).color(Color::Muted),
635	                                    )
636	                                    .into_any_element(),
637	                                NumberFieldMode::Edit => {
638	                                    let expected_text = format!("{}", self.value);
639	
640	                                    let editor = window.use_state(cx, {
641	                                        let expected_text = expected_text.clone();
642	
643	                                        move |window, cx| {
644	                                            let mut editor = Editor::single_line(window, cx);
645	
646	                                            editor.set_text_style_refinement(TextStyleRefinement {
647	                                                color: Some(cx.theme().colors().text),
648	                                                text_align: Some(TextAlign::Center),
649	                                                ..Default::default()
650	                                            });
651	
652	                                            editor.set_text(expected_text, window, cx);
653	
654	                                            let editor_weak = cx.entity().downgrade();
655	
656	                                            self.edit_editor.update(cx, |state, _| {
657	                                                *state = Some(editor_weak);
658	                                            });
659	
660	                                            editor
661	                                                .register_action::<MoveUp>({
662	                                                    let on_change = self.on_change.clone();
663	                                                    let editor_handle = cx.entity().downgrade();
664	                                                    move |_, window, cx| {
665	                                                        let Some(editor) = editor_handle.upgrade()
666	                                                        else {
667	                                                            return;
668	                                                        };
669	                                                        editor.update(cx, |editor, cx| {
670	                                                            if let Ok(current_value) =
671	                                                                editor.text(cx).parse::<T>()
672	                                                            {
673	                                                                let step =
674	                                                                    get_step(window.modifiers());
675	                                                                let new_value = change_value(
676	                                                                    current_value,
677	                                                                    step,
678	                                                                    ValueChangeDirection::Increment,
679	                                                                );
680	                                                                editor.set_text(
681	                                                                    format!("{}", new_value),
682	                                                                    window,
683	                                                                    cx,
684	                                                                );
685	                                                                on_change(&new_value, window, cx);
686	                                                            }
687	                                                        });
688	                                                    }
689	                                                })
690	                                                .detach();
691	
692	                                            editor
693	                                                .register_action::<MoveDown>({
694	                                                    let on_change = self.on_change.clone();
695	                                                    let editor_handle = cx.entity().downgrade();
696	                                                    move |_, window, cx| {
697	                                                        let Some(editor) = editor_handle.upgrade()
698	                                                        else {
699	                                                            return;
700	                                                        };
701	                                                        editor.update(cx, |editor, cx| {
702	                                                            if let Ok(current_value) =
703	                                                                editor.text(cx).parse::<T>()
704	                                                            {
705	                                                                let step =
706	                                                                    get_step(window.modifiers());
707	                                                                let new_value = change_value(
708	                                                                    current_value,
709	                                                                    step,
710	                                                                    ValueChangeDirection::Decrement,
711	                                                                );
712	                                                                editor.set_text(
713	                                                                    format!("{}", new_value),
714	                                                                    window,
715	                                                                    cx,
716	                                                                );
717	                                                                on_change(&new_value, window, cx);
718	                                                            }
719	                                                        });
720	                                                    }
721	                                                })
722	                                                .detach();
723	
724	                                            cx.on_focus_out(&editor.focus_handle(cx), window, {
725	                                                let on_change_state = self.on_change_state.clone();
726	                                                move |this, _, window, cx| {
727	                                                    if let Ok(parsed_value) =
728	                                                        this.text(cx).parse::<T>()
729	                                                    {
730	                                                        let new_value = clamp_value(parsed_value);
731	                                                        let on_change =
732	                                                            on_change_state.read(cx).clone();
733	
734	                                                        if let Some(on_change) = on_change.as_ref()
735	                                                        {
736	                                                            on_change(&new_value, window, cx);
737	                                                        }
738	                                                    };
739	                                                }
740	                                            })
741	                                            .detach();
742	
743	                                            editor
744	                                        }
745	                                    });
746	
747	                                    let focus_handle = editor.focus_handle(cx);
748	                                    let is_focused = focus_handle.is_focused(window);
749	
750	                                    if !is_focused {
