752	                                        let last_synced = *self.last_synced_value.read(cx);
753	
754	                                        // Detect if the value changed externally (e.g., reset button)
755	                                        let value_changed_externally = last_synced
756	                                            .map(|last| last != self.value)
757	                                            .unwrap_or(true);
758	
759	                                        let should_sync = if value_changed_externally {
760	                                            true
761	                                        } else {
762	                                            match current_text.parse::<T>().ok() {
763	                                                Some(parsed) => parsed == self.value,
764	                                                None => true,
765	                                            }
766	                                        };
