795	                                        .h_full()
796	                                        .track_focus(&focus_handle)
797	                                        .when(is_focused, |this| {
798	                                            this.border_1()
799	                                                .border_color(cx.theme().colors().border_focused)
800	                                        })
801	                                        .child(editor)
802	                                        .on_action::<menu::Confirm>({
803	                                            move |_, window, _| {
804	                                                window.blur();
805	                                            }
806	                                        })
807	                                        .into_any_element()
808	                                }
809	                            })
810	                    })
811	                    .map(|increment| {
812	                        let increment_handler = {
813	                            let step_value = step_value.clone();
814	
815	                            move |click: &ClickEvent, window: &mut Window, cx: &mut App| {
816	                                step_value(
817	                                    ValueChangeDirection::Increment,
818	                                    click.modifiers(),
819	                                    window,
820	                                    cx,
821	                                );
822	                            }
823	                        };
824	
825	                        increment.child(
